"""Correct legacy PF20/2 bias-reference via2 cuts/pads and requalify exported GDS."""
from pathlib import Path
import hashlib,json,re
import probe_gf180_mos_gate_cap as flow
from build_gf180_fixed_body_tg import rectangles
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 old=flow.BASE/'layout/gf180_pmos_bias_reference_grounded';qp=old/'qualification.json';q=json.loads(qp.read_text());files={Path(__file__),qp}
 for n,h in q['sha256'].items():
  pp=old/n;assert sha(pp)==h,n;files.add(pp)
 cell='gf180_pmos_bias_reference_fullroute_v2';out=flow.BASE/'layout'/cell;assert not out.exists();out.mkdir(parents=True);flow.OUT=out;shape=rectangles(old/'gf180_pmos_bias_reference_grounded.mag',0);cuts=[]
 for b in shape['via2']:
  x=(b[0]+b[2])//2;y=(b[1]+b[3])//2;cuts.append((x-28,y-28,x+28,y+28))
  for layer in ['metal2','metal3']:shape.setdefault(layer,[]).append((x-40,y-40,x+40,y+40))
 shape['via2']=cuts;lines=['magic','tech gf180mcuD','magscale 1 10','timestamp 0']
 for layer,boxes in shape.items():lines +=['<< '+layer+' >>']+['rect '+' '.join(map(str,b)) for b in boxes]
 labels=(old/'gf180_pmos_bias_reference_grounded.mag').read_text().split('<< labels >>')[1].lstrip('\r\n');lines+=['<< labels >>',labels];(out/(cell+'.mag')).write_text('\n'.join(lines));(out/'build_source.py').write_bytes(Path(__file__).read_bytes())
 log=flow.magic(f'load {cell}\ndrc on\ndrc style drc(full)\nselect top cell\ndrc check\ndrc catchup\ndrc count total\nputs [drc listall why]\nextract all\nfeedback save warnings.feedback\next2spice lvs\next2spice scale off\next2spice -o {cell}.spice\ngds write {cell}.gds\nfeedback save gds_warnings.feedback\nselect top cell\nputs "BBOX [box values]"\nquit -noprompt\n');(out/'extraction.log').write_text(log);dr=re.search(r'Total DRC errors found:\s*(\d+)',log);assert dr and int(dr[1])==0 and not (out/'gds_warnings.feedback').read_text() and not re.search(r'\d+ problems occurred',log),log[-4000:]
 header=re.search(r'(?m)^\.subckt[ \t]+'+cell+r'[ \t]*([^\n]*)',(out/(cell+'.spice')).read_text().replace('\n+',' '));assert header and header[1].split()==['BIAS','VDD','VSS'],'Actual source ports absent or reordered'
 ref=(old/'gf180_pmos_bias_reference_grounded.spice').read_text().replace('gf180_pmos_bias_reference_grounded','reference');(out/'reference.spice').write_text(ref);setup='/workspace/'+flow.PDK.relative_to(flow.ROOT).as_posix()+'/libs.tech/netgen/gf180mcuD_setup.tcl';lvs=flow.run(['netgen-lvs','-batch','lvs',cell+'.spice '+cell,'reference.spice reference',setup,'lvs.out']);(out/'netgen.log').write_text(lvs);assert 'Circuits match uniquely' in lvs
 cap=flow.magic(f'load {cell}\nextract do capacitance\nextract all\nfeedback save capacitance_warnings.feedback\next2spice lvs\next2spice cthresh 0\next2spice scale off\next2spice -o {cell}_cap.spice\nquit -noprompt\n');(out/'capacitance_extraction.log').write_text(cap);assert not (out/'warnings.feedback').read_text() and not (out/'capacitance_warnings.feedback').read_text()
 rd=flow.BASE/'verification/gds_roundtrip'/cell;rd.mkdir(parents=True);flow.OUT=rd;rl=flow.magic('gds read /workspace/'+(out/(cell+'.gds')).relative_to(flow.ROOT).as_posix()+f'\nload {cell}\ndrc on\ndrc style drc(full)\nselect top cell\ndrc check\ndrc catchup\ndrc count total\nextract all\nfeedback save roundtrip.feedback\next2spice lvs\next2spice scale off\next2spice -o roundtrip.spice\nquit -noprompt\n');(rd/'readback.log').write_text(rl);rdr=re.search(r'Total DRC errors found:\s*(\d+)',rl);rv=flow.run(['netgen-lvs','-batch','lvs','roundtrip.spice '+cell,'/workspace/'+(out/'reference.spice').relative_to(flow.ROOT).as_posix()+' reference',setup,'lvs.out']);(rd/'netgen.log').write_text(rv);assert rdr and int(rdr[1])==0 and 'Circuits match uniquely' in rv and not (rd/'roundtrip.feedback').read_text()
 header=re.search(r'(?m)^\.subckt[ \t]+'+cell+r'[ \t]*([^\n]*)',(rd/'roundtrip.spice').read_text().replace('\n+',' '));assert header and header[1].split()==['BIAS','VDD','VSS'],'Actual GDS ports absent or reordered'
 outputs=[out/(cell+s) for s in ['.mag','.gds','.spice','_cap.spice']]+[out/n for n in ['build_source.py','extraction.log','reference.spice','netgen.log','capacitance_extraction.log','warnings.feedback','gds_warnings.feedback','capacitance_warnings.feedback']];report={'cell':cell,'ports':['BIAS','VDD','VSS'],'magic_drc_count':0,'lvs_unique':True,'actual_source_ports_verified':True,'actual_gds_ports_verified':True,'drc_style':'drc(full)','gds_roundtrip_drc_count':0,'gds_roundtrip_lvs_unique':True,'extraction_feedback':'','bbox_um':[int(v)*.005 for v in re.search(r'BBOX ([-0-9 ]+)',log)[1].split()],'mos_count':1,'native_mim_count':0,'scope':'Same native diode-connectedPF20/2 with source/bodyVDD and substrateVSS. Five VIA2 cut regions corrected from0.26 to0.28um and enclosingM2/M3 pads to0.40um; transistor dimensions/connectivity preserved. New full DRC/sourceLVS/exportedGDS reimportDRC/LVS pass. External master current still required; no autonomous reference/noise/PVT/model/full-chip acceptance.','sha256':{pp.name:sha(pp) for pp in outputs},'input_sha256':{pp.relative_to(flow.ROOT).as_posix():sha(pp) for pp in sorted(files)},'gds_roundtrip_sha256':{pp.relative_to(flow.ROOT).as_posix():sha(pp) for pp in [rd/n for n in ['readback.log','netgen.log','roundtrip.spice','roundtrip.feedback']]}};(out/'qualification.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'report':str(out/'qualification.json'),'mos_count':1},indent=2))
if __name__=='__main__':main()
